{
  "passageId": "audio-perceptual-coding",
  "items": [
    {
      "id": "R1",
      "type": "PROCESS",
      "otherName": "",
      "reason": "장치를 준비하고 소리를 입력한 다음 진동 변환과 홈 기록을 수행하는 단계의 순서이므로 과정 관계이다."
    },
    {
      "id": "R2",
      "type": "CAUSE",
      "otherName": "",
      "reason": "나팔의 진동이 바늘에 전달되어 그 형태에 따른 홈을 만드는 실제 물리적 작용이므로 인과 관계이다."
    },
    {
      "id": "R3",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "판에 홈을 만드는 행위가 소리를 저장하기 위한 수단이므로 수단·목적 관계이다."
    },
    {
      "id": "R4",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "초기의 아날로그 기록에서 현재의 디지털 저장으로 시대와 설명 대상이 넘어가므로 판별 순서 3의 전개 관계이다."
    },
    {
      "id": "R5",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "동일한 개수의 비트를 할당한다는 일반적 설명을 통상적인 16비트 할당으로 구체화한다."
    },
    {
      "id": "R6",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "데이터 양이 많다는 사실이 압축해야 한다는 당위의 이유로 제시되므로 근거·도출 관계이다."
    },
    {
      "id": "R7",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "압축이 필요하다는 문제에 대해 실제로 이용하는 기술인 지각부호화를 해결 방법으로 제시한다."
    },
    {
      "id": "R8",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "지각부호화가 청각 특성을 이용한다는 설명을 최소가청강도와 차폐라는 구체적인 특성으로 풀어 준다."
    },
    {
      "id": "R9",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "감지 가능한 소리 크기의 최솟값이라는 정의로부터 그보다 큰 소리는 들린다는 판단이 도출된다."
    },
    {
      "id": "R10",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "감지 가능한 소리 크기의 최솟값이라는 정의로부터 그보다 작은 소리는 들리지 않는다는 판단이 도출된다."
    },
    {
      "id": "R11",
      "type": "CONDITION",
      "otherName": "",
      "reason": "소리 크기가 최소가청강도보다 큰지 작은지에 따라 가청 여부가 갈리므로 판별 순서 11의 조건 관계이다."
    },
    {
      "id": "R12",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "특정 주파수 구간에서 작은 소리도 들린다는 사례가 주파수별 최소가청강도를 구체적으로 보여 준다."
    },
    {
      "id": "R13",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "100 Hz 이하에서는 더 큰 소리가 필요하다는 사례가 주파수별 최소가청강도의 차이를 구체화한다."
    },
    {
      "id": "R14",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "서로 다른 주파수 구간을 들을 수 있는 소리 크기라는 같은 기준에서 비교하여 차이를 보여 준다."
    },
    {
      "id": "R15",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "청각 특성으로 소개된 차폐를 그 발생 조건과 임계대역 및 차폐 문턱값으로 자세히 풀어 설명한다."
    },
    {
      "id": "R16",
      "type": "CONDITION",
      "otherName": "",
      "reason": "두 소리의 주파수가 가까운지 충분히 떨어져 있는지에 따라 차폐 발생 여부가 갈린다."
    },
    {
      "id": "R17",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "차폐가 발생하는 주파수 범위를 임계대역이라고 이름 붙이고 그 뜻을 규정한다."
    },
    {
      "id": "R18",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "주파수에 따라 임계대역 폭이 다르다는 설명을 고음과 저음의 구체적인 비교로 풀어 준다."
    },
    {
      "id": "R19",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "가청 한계라는 같은 기준에서 조용할 때의 최소가청강도와 차폐를 고려한 차폐 문턱값을 구별한다."
    },
    {
      "id": "R20",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "청각 특성을 이용해 압축한다는 설명을 문턱값 산출과 비트 할당 및 소리 제거의 세부 절차로 구체화한다."
    },
    {
      "id": "R21",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "청각 현상을 설명하는 임계대역 개념을 오디오 신호를 분할하는 기술적 기준으로 가져다 쓴다."
    },
    {
      "id": "R22",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "청각의 최소 감지 크기라는 개념을 지각부호화의 차폐 문턱값 산출에 적용한다."
    },
    {
      "id": "R23",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "차폐를 일으키는 소리라는 청각 개념을 지각부호화의 차폐 문턱값 산출에 적용한다."
    },
    {
      "id": "R24",
      "type": "PROCESS",
      "otherName": "",
      "reason": "오디오 신호를 임계대역으로 나눈 뒤 각 대역에서 차폐 문턱값을 구하는 처리 순서이다."
    },
    {
      "id": "R25",
      "type": "PROCESS",
      "otherName": "",
      "reason": "앞 단계에서 산출한 차폐 문턱값을 바탕으로 다음 단계의 비트 할당을 진행하므로 과정 관계이다."
    },
    {
      "id": "R26",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "문턱값과의 차이가 큰 소리에 비트를 많이 할당하는 것이 소리 손실을 낮추기 위해 선택한 수단이다."
    },
    {
      "id": "R27",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "문턱값 미만의 소리가 들리지 않는다는 사실이 그 소리를 제거하는 처리의 이유로 제시된다."
    },
    {
      "id": "R28",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "실제 감지 가능한 소리 크기의 최솟값이라는 정의에서 문턱값 미만의 소리는 들리지 않는다는 판단이 도출된다."
    },
    {
      "id": "R29",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "비트 할당 방식이라는 같은 기준에서 일반 오디오 신호의 균일 할당과 지각부호화의 차등 할당이 대비된다."
    },
    {
      "id": "R30",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "소리별 비트 할당으로 손실을 낮추는 세부 설명을 품질 저하를 최소화하는 압축 방식이라는 일반적 성질로 종합한다."
    },
    {
      "id": "R31",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "차폐 문턱값 미만의 소리를 제거하는 처리가 감도가 낮은 소리를 제거한다는 지각부호화 설명의 구체적인 구현이다."
    }
  ]
}

